CAT = "aatl2Transactions"; SEG = "TRN"
Q = [
("Goods have a list price of £640. The customer gets a 15% trade discount, and VAT is charged at 20%. The invoice total is:",
 "£652.80", ["£768.00", "£544.00", "£672.00"],
 "Net = £640 x 85% = £544. VAT = £544 x 20% = £108.80. Total = £652.80. Leaving out the trade discount gives £768."),
("A wholesaler gives customers who are themselves in business a lower price, shown on the invoice. This is a:",
 "Trade discount", ["Bulk discount", "Prompt payment discount", "Discount received"],
 "A trade discount is given to trade customers and deducted on the invoice. A bulk discount depends on the size of the order, and a prompt payment discount on paying early."),
("A customer orders 500 units and gets an extra price reduction because of the size of the order. This is a:",
 "Bulk discount", ["Trade discount", "Prompt payment discount", "Discount allowed"],
 "A bulk discount rewards a large quantity and is deducted on the invoice. Discount allowed is the bookkeeping name for prompt payment discount given to customers."),
("An invoice offers a 2% discount for payment within 10 days. If the customer pays in time, how is the discount usually recorded?",
 "A credit note is issued for it", ["The invoice is reissued for less", "It is deducted on the first invoice", "It is left out of the VAT records"],
 "The invoice is raised at the full price. When the customer takes the prompt payment discount, the seller issues a credit note that reduces both the net amount and the VAT."),
("An invoice totals £1,200 including VAT at 20%. The customer pays in time and takes a 2.5% prompt payment discount. The credit note total, VAT included, is:",
 "£30.00", ["£25.00", "£36.00", "£24.00"],
 "2.5% x £1,200 = £30, made up of £25 net and £5 VAT. £25 is only the net part, and £36 adds VAT on top of an amount that already includes it."),
("An invoice totals £1,746 including VAT at 20%. The VAT on it is:",
 "£291.00", ["£349.20", "£1,455.00", "£174.60"],
 "VAT in a VAT-inclusive total at 20% is total x 20/120 = £1,746 / 6 = £291. Taking 20% of the total (£349.20) charges VAT on VAT."),
("Sales daybook totals for a week are: total £18,720, VAT £3,120, net £15,600. Which entry posts the net column?",
 "Credit sales £15,600", ["Debit sales £15,600", "Credit sales £18,720", "Debit VAT £3,120"],
 "Net sales are credited to the sales account. The total goes to the debit of the receivables ledger control account and the VAT to the credit of VAT."),
("The total column of the sales daybook is debited to the:",
 "Receivables ledger control account", ["Sales account", "VAT control account", "Bank account"],
 "Customers owe the full amount including VAT, so the total is debited to the receivables ledger control account. Sales and VAT are the credit entries."),
("A customer pays £2,950 against two invoices of £1,800 and £1,250. What is the discrepancy?",
 "Underpaid by £100", ["Overpaid by £100", "Underpaid by £50", "Paid in full"],
 "The invoices total £1,800 + £1,250 = £3,050. The payment of £2,950 is £100 short, so the customer should be asked for the balance."),
("A customer deducts a prompt payment discount, but pays after the discount period has ended. The seller should:",
 "Ask the customer for the shortfall", ["Issue the usual discount credit note", "Write the shortfall off", "Treat it as a bulk discount"],
 "The discount was only available for payment within the stated period. Taking it late is an incorrect discount, so the shortfall is still owed."),
("Which document should a buyer match with a supplier's invoice to confirm the goods actually arrived?",
 "Goods received note", ["Purchase order", "Quotation", "Statement of account"],
 "The goods received note records what was delivered. The purchase order shows what was ordered, which is not proof of delivery."),
("A supplier's invoice charges for 30 boxes, but the goods received note shows 26 boxes. The buyer should:",
 "Ask for a credit note for 4 boxes", ["Pay for 30 and note it", "Return the 26 boxes", "Pay nothing until next month"],
 "The buyer should only pay for goods received. Asking for a credit note for the 4 missing boxes corrects the supplier's account."),
("A supplier's quotation agreed a 10% trade discount, but the invoice deducts only 5%. This is:",
 "An incorrect discount", ["A timing difference", "A non-delivery", "A duplicated transaction"],
 "Checking the invoice against the quotation shows the wrong discount. The supplier should issue a credit note for the difference."),
("A business receives a credit note from a supplier for goods it sent back. It is recorded in the:",
 "Purchases returns daybook", ["Sales returns daybook", "Discounts received daybook", "Purchases daybook"],
 "Credit notes received from suppliers for returns go in the purchases returns daybook. The sales returns daybook is for credit notes the business issues."),
("Purchases daybook totals: net £7,450, VAT £1,490, total £8,940. Which entry posts the total column?",
 "Credit payables control £8,940", ["Debit payables ledger control £8,940", "Credit purchases £8,940", "Debit VAT control £8,940"],
 "The business owes suppliers the full amount, so the total is credited to the payables ledger control account. Purchases (£7,450) and VAT (£1,490) are debited."),
("A supplier's statement shows £3,415 owed. The supplier's account in the payables ledger shows £2,980. The £435 difference is a payment sent on the last day of the month. This is:",
 "A timing difference", ["An overpayment", "A duplicated invoice", "A missing credit note"],
 "The payment is in the business's records but had not reached the supplier when the statement was printed. £3,415 - £2,980 = £435, the payment."),
("Goods listed at £2,400 are bought with a 12.5% bulk discount. VAT at 20% is then added. The VAT is:",
 "£420.00", ["£480.00", "£350.00", "£300.00"],
 "Net = £2,400 x 87.5% = £2,100. VAT = £2,100 x 20% = £420. Charging VAT before the discount gives £480."),
("An invoice is £850 plus VAT at 20%, with a 3% prompt payment discount. If the business pays in time, it pays:",
 "£989.40", ["£1,020.00", "£994.50", "£824.50"],
 "The invoice total is £1,020. The discount reduces the net and the VAT, so the business pays 97% of £1,020 = £989.40. Taking 3% of the net only gives £994.50."),
("A customer owes several invoices of different ages and pays part of the total without a remittance advice. The payment is usually allocated against:",
 "The oldest items first", ["The newest invoice first", "The largest invoice only", "Any credit notes first"],
 "Unless the customer says otherwise, a payment clears the oldest balances first, starting with any opening balance. Credit notes reduce what is owed; they are not paid off."),
("A quotation is:",
 "A price offered before an order", ["A request for payment", "Proof that goods arrived", "A refund for returned goods"],
 "A quotation tells the customer the price and terms before they order. The invoice is the request for payment."),
]
